functions._atsState:
function _atsState() {
  if (!window._atsState_) {
    window._atsState_ = {
      templates: [],
      currentId: null,
      draft: null,           // unsaved edits to current template
      mockValues: {},
      filterText: "",
      filterStatus: "all",   // all | active | draft | archived
      saveTimer: null,
      versions: {},
      aiBusy: false,
    };
  }
  return window._atsState_;
}

// ── IDB helpers ─────────────────────────────────────────────────────

functions._atsLoadAll:
function _atsLoadAll() {
  if (!window.eli || !window.eli.storage) return Promise.resolve([]);
  return window.eli.storage.getAll("bd_templates").then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && r.id && String(r.id).charAt(0) !== "_";
    });
  }).catch(function () { return []; });
}

functions._atsSave:
function _atsSave(tpl) {
  if (!tpl || !tpl.id) return Promise.reject(new Error("missing id"));
  tpl.lastUpdated = Date.now();
  return window.eli.storage.put("bd_templates", tpl);
}

functions._atsDeleteById:
function _atsDeleteById(id) {
  return window.eli.storage.delete("bd_templates", id);
}

// ── Tag + section extraction ────────────────────────────────────────
// Walks the template's `content` field (string — sometimes JSON, sometimes
// plain text/OOXML) and pulls out replacement tags. Recognizes `{tag}`,
// `{{tag}}`, and `<<tag>>` patterns. Dedups + returns sorted unique list.

functions._atsExtractTags:
function _atsExtractTags(content) {
  if (!content) return [];
  var s = String(content);
  var found = {};
  var patterns = [
    /\{\{?\s*([A-Za-z][A-Za-z0-9_\-\.]{0,60})\s*\}?\}/g,
    /<<\s*([A-Za-z][A-Za-z0-9_\-\.]{0,60})\s*>>/g,
  ];
  patterns.forEach(function (re) {
    var m;
    while ((m = re.exec(s)) !== null) {
      var name = m[1];
      if (!name) continue;
      // Filter out obvious OOXML attribute fragments (rsid, p_id, etc.).
      if (/^(rsid|p_id|w_|xml|xmlns)/i.test(name)) continue;
      found[name] = (found[name] || 0) + 1;
    }
  });
  return Object.keys(found).sort();
}

// Parse the content's JSON envelope (when present) to get sections.

functions._atsParseSections:
function _atsParseSections(content) {
  if (!content) return [];
  var s = String(content).trim();
  if (s.charAt(0) !== "{") return [];
  try {
    var parsed = JSON.parse(s);
    if (Array.isArray(parsed.sections)) return parsed.sections;
  } catch (e) { /* fall through */ }
  return [];
}

// ── Doc snapshot / restore (the "restart" capability) ──────────────
// Snapshot the doc body's OOXML to IDB under STORE_CONFIG row id
// _template_studio_snapshot_<templateId>. Restore writes it back.

functions._atsSnapshotDoc:
function _atsSnapshotDoc(templateId) {
  if (!window.eli || !window.eli.host || !window.eli.host.runRaw) return Promise.resolve(false);
  return window.eli.host.runRaw("ats:snapshot", function (context) {
    var body = context.document.body;
    var ooxml = body.getOoxml();
    return context.sync().then(function () {
      return ooxml.value;
    });
  }).then(function (xml) {
    return window.eli.storage.put("config", {
      key: "_template_studio_snapshot_" + templateId,
      ooxml: xml,
      capturedAt: Date.now(),
    }).then(function () { return true; });
  }).catch(function () { return false; });
}

functions._atsRestoreDoc:
function _atsRestoreDoc(templateId) {
  return window.eli.storage.get("config", "_template_studio_snapshot_" + templateId).then(function (row) {
    if (!row || !row.ooxml) {
      if (typeof showToast === "function") showToast("No snapshot to restore.", "warn");
      return false;
    }
    return window.eli.host.runRaw("ats:restore", function (context) {
      context.document.body.insertOoxml(row.ooxml, Word.InsertLocation.replace);
      return context.sync();
    }).then(function () {
      if (typeof showToast === "function") showToast("✓ Restored to pre-test snapshot", "ok");
      return true;
    });
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Restore failed: " + (err && err.message || "unknown"), "err");
    return false;
  });
}

// Apply a template (full or single section) into the doc body. Uses
// build_draft's existing `_loadTemplateToWord` if available; otherwise
// inserts the raw content as OOXML / text.

functions._atsApplyToDoc:
function _atsApplyToDoc(content) {
  if (!content) return Promise.reject(new Error("empty content"));
  // Try build_draft's loader first (preserves headers/footers etc.).
  if (typeof window.loadTemplateToWord === "function") {
    try { return Promise.resolve(window.loadTemplateToWord(content)); }
    catch (e) { /* fall through */ }
  }
  // Inline fallback — handles both JSON-envelope and plain-text content.
  return window.eli.host.runRaw("ats:apply", function (context) {
    var body = context.document.body;
    var s = String(content).trim();
    if (s.charAt(0) === "{") {
      try {
        var parsed = JSON.parse(s);
        if (parsed.body) body.insertOoxml(parsed.body, Word.InsertLocation.replace);
        else body.insertText(s, Word.InsertLocation.replace);
      } catch (e) {
        body.insertText(s, Word.InsertLocation.replace);
      }
    } else {
      body.insertText(s, Word.InsertLocation.replace);
    }
    return context.sync();
  });
}

// Apply only one section's body. Used by "Test this section only".

functions._atsApplySection:
function _atsApplySection(section) {
  if (!section || !section.body) return Promise.reject(new Error("section has no body"));
  return window.eli.host.runRaw("ats:apply_section", function (context) {
    context.document.body.insertOoxml(section.body, Word.InsertLocation.replace);
    return context.sync();
  });
}

// ── Mock-values rendering (text-only preview, no Word touch) ───────

functions._atsRenderPreview:
function _atsRenderPreview(content, mockValues) {
  var out = String(content || "");
  // Strip JSON envelope to just the body text.
  if (out.charAt(0) === "{") {
    try {
      var parsed = JSON.parse(out);
      out = String(parsed.body || "");
    } catch (e) { /* keep original */ }
  }
  // Strip OOXML tags to plain text — quick preview only, lossy.
  out = out.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();
  // Substitute mock values.
  var mv = mockValues || {};
  Object.keys(mv).forEach(function (k) {
    var re1 = new RegExp("\\{\\{?\\s*" + k.replace(/[\.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*\\}?\\}", "g");
    var re2 = new RegExp("<<\\s*" + k.replace(/[\.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*>>", "g");
    out = out.replace(re1, mv[k] || "").replace(re2, mv[k] || "");
  });
  return out;
}

// ── Line diff (current draft vs saved version) ─────────────────────

functions._atsSimpleDiff:
function _atsSimpleDiff(oldS, newS) {
  var a = String(oldS || "").split(/\r?\n/);
  var b = String(newS || "").split(/\r?\n/);
  var lcs = _atsLcs(a, b);
  var i = 0, j = 0, out = [];
  lcs.forEach(function (line) {
    while (i < a.length && a[i] !== line) { out.push({ t: "-", s: a[i++] }); }
    while (j < b.length && b[j] !== line) { out.push({ t: "+", s: b[j++] }); }
    out.push({ t: "=", s: line }); i++; j++;
  });
  while (i < a.length) out.push({ t: "-", s: a[i++] });
  while (j < b.length) out.push({ t: "+", s: b[j++] });
  return out;
}

functions._atsLcs:
function _atsLcs(a, b) {
  var m = a.length, n = b.length;
  if (!m || !n) return [];
  var dp = [];
  for (var i = 0; i <= m; i++) { dp[i] = []; for (var j = 0; j <= n; j++) dp[i][j] = 0; }
  for (var i2 = 1; i2 <= m; i2++) {
    for (var j2 = 1; j2 <= n; j2++) {
      dp[i2][j2] = (a[i2 - 1] === b[j2 - 1]) ? dp[i2 - 1][j2 - 1] + 1 : Math.max(dp[i2 - 1][j2], dp[i2][j2 - 1]);
    }
  }
  var out = [], ii = m, jj = n;
  while (ii > 0 && jj > 0) {
    if (a[ii - 1] === b[jj - 1]) { out.unshift(a[ii - 1]); ii--; jj--; }
    else if (dp[ii - 1][jj] >= dp[ii][jj - 1]) ii--;
    else jj--;
  }
  return out;
}

// ── AI integration ──────────────────────────────────────────────────
// Each AI helper sends a focused prompt to eli.ai.completeJSON and
// expects a specific shape back. All wrapped in try/catch + busy
// indicator so the panel never freezes if the AI fails.

functions._atsAIReview:
function _atsAIReview(tpl) {
  if (!window.eli.ai || !window.eli.ai.completeJSON) return Promise.reject(new Error("AI unavailable"));
  var content = String(tpl.content || "");
  var sample = content.length > 8000 ? content.slice(0, 8000) + "\n[...truncated]" : content;
  var tags = _atsExtractTags(content);
  var prompt =
    "You are a contract template auditor for Colgate-Palmolive's legal team.\n\n" +
    "Review the template below for:\n" +
    "  1. Syntax issues (unmatched braces, malformed placeholders, broken refs)\n" +
    "  2. Semantic issues (clauses that contradict each other, missing defined terms)\n" +
    "  3. Missing standard clauses for a " + (tpl.agreementType || "general contract") + "\n" +
    "  4. Drafting risks (vague terms, asymmetric obligations, missing carve-outs)\n\n" +
    "Detected tags: " + (tags.length ? tags.join(", ") : "(none)") + "\n\n" +
    "Return strict raw JSON: {\"issues\": [{\"severity\": \"error|warn|info\", \"title\": \"<short>\", \"detail\": \"<one-sentence explanation>\"}]}\n\n" +
    "TEMPLATE CONTENT:\n" + sample;
  return window.eli.ai.completeJSON(prompt);
}

functions._atsAIDescribe:
function _atsAIDescribe(tpl) {
  if (!window.eli.ai || !window.eli.ai.complete) return Promise.reject(new Error("AI unavailable"));
  var content = String(tpl.content || "");
  var sample = content.length > 6000 ? content.slice(0, 6000) + "\n[...truncated]" : content;
  var prompt =
    "Summarize this contract template for an admin in 3-5 sentences. State the agreement type, " +
    "key obligations, notable risk allocations, and any unusual provisions. Plain prose, no headers.\n\n" +
    "TEMPLATE: " + sample;
  return window.eli.ai.complete(prompt, { maxTokens: 600 });
}

functions._atsAISuggestMockValues:
function _atsAISuggestMockValues(tpl) {
  if (!window.eli.ai || !window.eli.ai.completeJSON) return Promise.reject(new Error("AI unavailable"));
  var tags = _atsExtractTags(tpl.content);
  if (!tags.length) return Promise.resolve({});
  var prompt =
    "For these contract-template placeholders, generate realistic test values that an admin " +
    "could use to preview the template. Agreement type: " + (tpl.agreementType || "general") + ".\n\n" +
    "Tags: " + tags.join(", ") + "\n\n" +
    "Return strict raw JSON keyed by tag name → realistic value (string).";
  return window.eli.ai.completeJSON(prompt);
}

functions._atsAIImprovements:
function _atsAIImprovements(tpl) {
  if (!window.eli.ai || !window.eli.ai.completeJSON) return Promise.reject(new Error("AI unavailable"));
  var content = String(tpl.content || "");
  var sample = content.length > 8000 ? content.slice(0, 8000) + "\n[...truncated]" : content;
  var prompt =
    "Suggest 3-7 concrete improvements to this contract template (a " + (tpl.agreementType || "contract") +
    ") from Colgate-Palmolive's perspective. Focus on clauses that should be added, tightened, " +
    "or rebalanced. Return strict raw JSON: {\"improvements\": [{\"area\": \"<clause name>\", \"suggestion\": \"<concrete change>\", \"rationale\": \"<why>\"}]}.\n\n" +
    "TEMPLATE: " + sample;
  return window.eli.ai.completeJSON(prompt);
}

// ── Render helpers ──────────────────────────────────────────────────

functions._atsRenderList:
function _atsRenderList() {
  var st = _atsState();
  var listEl = document.getElementById("atsList");
  if (!listEl) return;
  var f = (st.filterText || "").toLowerCase();
  var rows = st.templates.filter(function (t) {
    if (st.filterStatus !== "all" && (t.status || "active") !== st.filterStatus) return false;
    if (!f) return true;
    var hay = ((t.name || "") + " " + (t.agreementType || "") + " " + (t.id || "")).toLowerCase();
    return hay.indexOf(f) !== -1;
  });
  if (!rows.length) {
    listEl.innerHTML = '<div style="padding:24px; text-align:center; color:#94a3b8; font-size:11px;">' +
      (f ? "No templates match." : "No templates yet. Click Import or use Build Draft to save one.") +
      '</div>';
    return;
  }
  listEl.innerHTML = rows.map(function (t) {
    var status = (t.status || "active");
    var statusCls = "_ats_pill_" + status;
    var locked = t.locked ? '<span class="_ats_card_pill _ats_pill_locked">🔒</span>' : '';
    var active = (t.id === st.currentId) ? " _ats_card_active" : "";
    var size = String(t.content || "").length;
    var when = t.lastUpdated ? new Date(t.lastUpdated).toLocaleString() : "—";
    return '<div class="_ats_card' + active + '" data-ats-id="' + _atsEsc(t.id) + '">' +
      '<div class="_ats_card_title">' + _atsEsc(t.name || t.id) + '</div>' +
      '<div class="_ats_card_meta">' +
        '<span class="_ats_card_pill ' + statusCls + '">' + status + '</span>' + locked +
        '<span>' + _atsEsc(t.agreementType || "—") + '</span>' +
        '<span>· ' + Math.round(size / 1024) + ' KB</span>' +
      '</div>' +
      '<div class="_ats_card_meta" style="margin-top:3px; font-size:9px;">' + _atsEsc(when) + '</div>' +
      '</div>';
  }).join("");
  listEl.querySelectorAll("._ats_card").forEach(function (c) {
    c.onclick = function () {
      _atsSelectTemplate(c.getAttribute("data-ats-id"));
    };
  });
}

functions._atsSelectTemplate:
function _atsSelectTemplate(id) {
  var st = _atsState();
  if (st.draft && st.currentId !== id) {
    var unsaved = st.draft._dirty;
    if (unsaved && typeof window.eli.ui.confirm === "function") {
      window.eli.ui.confirm({
        variant: "warning", title: "Discard unsaved changes?",
        message: "You have unsaved edits. Switch templates anyway?",
        confirmLabel: "Discard", cancelLabel: "Cancel",
      }).then(function (ok) {
        if (ok) { st.draft = null; _atsSelectTemplate(id); }
      });
      return;
    }
  }
  st.currentId = id;
  st.draft = null;
  st.mockValues = {};
  _atsRenderList();
  _atsRenderEditor();
  _atsRenderTestPanel();
}

functions._atsCurrentTemplate:
function _atsCurrentTemplate() {
  var st = _atsState();
  if (st.draft) return st.draft;
  return st.templates.find(function (t) { return t.id === st.currentId; }) || null;
}

functions._atsRenderEditor:
function _atsRenderEditor() {
  var st = _atsState();
  var centerEl = document.getElementById("atsCenter");
  if (!centerEl) return;
  var tpl = _atsCurrentTemplate();
  if (!tpl) {
    centerEl.innerHTML =
      '<div class="_ats_center_empty">' +
        '<div class="_ats_center_empty_icon">📋</div>' +
        '<div class="_ats_center_empty_title">No template selected</div>' +
        '<div class="_ats_center_empty_sub">Pick one from the left, or click <b>Import</b> / <b>New</b>.</div>' +
      '</div>';
    return;
  }
  var tags = _atsExtractTags(tpl.content);
  var sections = _atsParseSections(tpl.content);
  centerEl.innerHTML =
    // Metadata
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📌 Metadata</div>' +
        '<div class="_ats_section_actions">' +
          '<button class="_ats_btn _ats_btn_ghost" id="atsDuplicate">📋 Duplicate</button>' +
          '<button class="_ats_btn _ats_btn_ghost" id="atsExport">⬇ Export JSON</button>' +
          '<button class="_ats_btn _ats_btn_ghost" id="atsLock">' + (tpl.locked ? "🔓 Unlock" : "🔒 Lock") + '</button>' +
          '<button class="_ats_btn _ats_btn_danger" id="atsDelete">🗑 Delete</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ats_meta_grid">' +
        '<div>' +
          '<div class="_ats_field_label">Name</div>' +
          '<input id="atsFieldName" class="_ats_input" type="text" value="' + _atsEsc(tpl.name || "") + '">' +
        '</div>' +
        '<div>' +
          '<div class="_ats_field_label">Agreement Type</div>' +
          '<input id="atsFieldType" class="_ats_input" type="text" value="' + _atsEsc(tpl.agreementType || "") + '" placeholder="e.g. Non-Disclosure Agreement">' +
        '</div>' +
      '</div>' +
      '<div class="_ats_meta_grid">' +
        '<div>' +
          '<div class="_ats_field_label">Status</div>' +
          '<select id="atsFieldStatus" class="_ats_select">' +
            ['active', 'draft', 'archived'].map(function (s) {
              return '<option value="' + s + '"' + (((tpl.status || "active") === s) ? " selected" : "") + '>' + s + '</option>';
            }).join("") +
          '</select>' +
        '</div>' +
        '<div>' +
          '<div class="_ats_field_label">ID (read-only)</div>' +
          '<input class="_ats_input" type="text" value="' + _atsEsc(tpl.id) + '" readonly style="background:#f1f5f9; color:#64748b; font-family:ui-monospace,monospace;">' +
        '</div>' +
      '</div>' +
    '</div>' +
    // Outline (tags + sections)
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">🧩 Outline</div>' +
      '</div>' +
      '<div class="_ats_outline_grid">' +
        '<div class="_ats_outline_box">' +
          '<div class="_ats_outline_head">Tags / Placeholders <span class="_ats_outline_head_count">' + tags.length + '</span></div>' +
          (tags.length
            ? '<div class="_ats_tag_list">' + tags.map(function (t) {
                return '<span class="_ats_tag" data-ats-tag="' + _atsEsc(t) + '">' + _atsEsc(t) + '</span>';
              }).join("") + '</div>'
            : '<div style="font-size:10px; color:#94a3b8;">No tags detected. Use {tagName} or {{tagName}} in the content.</div>') +
        '</div>' +
        '<div class="_ats_outline_box">' +
          '<div class="_ats_outline_head">Sections <span class="_ats_outline_head_count">' + sections.length + '</span></div>' +
          (sections.length
            ? '<div class="_ats_section_list">' + sections.map(function (s, i) {
                var label = "Section " + (i + 1) + (s.headerType ? " · " + s.headerType : "");
                return '<div class="_ats_section_row">' +
                  '<span class="_ats_section_row_label">' + _atsEsc(label) + '</span>' +
                  '<button class="_ats_section_row_test" data-ats-secidx="' + i + '">▶ Test</button>' +
                  '</div>';
              }).join("") + '</div>'
            : '<div style="font-size:10px; color:#94a3b8;">No section breakdown — content is plain or single-section.</div>') +
        '</div>' +
      '</div>' +
    '</div>' +
    // Raw content editor
    '<div class="_ats_section">' +
      '<div class="_ats_section_head">' +
        '<div class="_ats_section_title">📝 Content (raw)</div>' +
        '<div class="_ats_section_actions">' +
          '<button class="_ats_btn _ats_btn_ghost" id="atsDiff">🔍 Diff vs saved</button>' +
          '<button class="_ats_btn _ats_btn_success" id="atsSave">💾 Save</button>' +
        '</div>' +
      '</div>' +
      '<textarea id="atsFieldContent" class="_ats_textarea _ats_textarea_large" spellcheck="false">' + _atsEsc(tpl.content || "") + '</textarea>' +
    '</div>';

  // Wire field edits → mark draft
  ["atsFieldName", "atsFieldType", "atsFieldStatus", "atsFieldContent"].forEach(function (id) {
    var el = document.getElementById(id);
    if (!el) return;
    var ev = (id === "atsFieldStatus") ? "change" : "input";
    el.addEventListener(ev, _atsOnFieldEdit);
  });
  document.getElementById("atsDuplicate").onclick = _atsActionDuplicate;
  document.getElementById("atsExport").onclick = _atsActionExport;
  document.getElementById("atsLock").onclick = _atsActionLock;
  document.getElementById("atsDelete").onclick = _atsActionDelete;
  document.getElementById("atsDiff").onclick = _atsActionDiff;
  document.getElementById("atsSave").onclick = _atsActionSave;
  centerEl.querySelectorAll("[data-ats-secidx]").forEach(function (b) {
    b.onclick = function () { _atsActionTestSection(parseInt(b.getAttribute("data-ats-secidx"), 10)); };
  });
  centerEl.querySelectorAll("[data-ats-tag]").forEach(function (t) {
    t.onclick = function () {
      var name = t.getAttribute("data-ats-tag");
      var input = document.getElementById("atsFieldContent");
      if (input) input.focus();
      var idx = String(input.value || "").indexOf("{" + name);
      if (idx === -1) idx = String(input.value || "").indexOf("<<" + name);
      if (idx !== -1) {
        input.setSelectionRange(idx, idx + name.length + 4);
      }
    };
  });
}

functions._atsRenderTestPanel:
function _atsRenderTestPanel() {
  var rightEl = document.getElementById("atsRight");
  if (!rightEl) return;
  var tpl = _atsCurrentTemplate();
  if (!tpl) {
    rightEl.innerHTML = '<div class="_ats_right_head">⚙ Testing & AI</div>' +
      '<div class="_ats_right_section" style="color:#94a3b8; font-size:11px;">Select a template to test.</div>';
    return;
  }
  var st = _atsState();
  var tags = _atsExtractTags(tpl.content);
  var mockHtml = tags.length
    ? '<div class="_ats_mocklist">' + tags.map(function (t) {
        var v = st.mockValues[t] || "";
        return '<div class="_ats_mockrow">' +
          '<div class="_ats_mockrow_label" title="' + _atsEsc(t) + '">' + _atsEsc(t) + '</div>' +
          '<input data-ats-mock="' + _atsEsc(t) + '" value="' + _atsEsc(v) + '" placeholder="(test value)">' +
          '</div>';
      }).join("") + '</div>'
    : '<div style="font-size:10px; color:#94a3b8;">No tags detected.</div>';

  rightEl.innerHTML =
    '<div class="_ats_right_head">⚙ Testing & AI</div>' +
    // Action bar
    '<div class="_ats_right_section">' +
      '<div class="_ats_actionbar">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsTest">▶ Test in Word</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsRestore">↩ Restore pre-test</button>' +
        '<button class="_ats_btn _ats_btn_gold" id="atsPreviewBtn">👁 Refresh preview</button>' +
      '</div>' +
    '</div>' +
    // Mock values
    '<div class="_ats_right_section">' +
      '<div class="_ats_section_title" style="margin-bottom:8px;">🧪 Mock OARS values <button class="_ats_btn _ats_btn_ghost" id="atsSuggestValues" style="float:right; padding:4px 8px; font-size:9px;">💡 AI Suggest</button></div>' +
      mockHtml +
    '</div>' +
    // Preview
    '<div class="_ats_right_section">' +
      '<div class="_ats_section_title" style="margin-bottom:8px;">📜 Rendered preview</div>' +
      '<div class="_ats_preview" id="atsPreview"><span class="_ats_preview_empty">Click Refresh preview to render.</span></div>' +
    '</div>' +
    // AI panel
    '<div class="_ats_right_section">' +
      '<div class="_ats_section_title" style="margin-bottom:8px;">🤖 AI assistance</div>' +
      '<div class="_ats_actionbar">' +
        '<button class="_ats_btn _ats_btn_primary" id="atsAIReview">🔎 Review for errors</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsAIDescribe">📝 Describe template</button>' +
        '<button class="_ats_btn _ats_btn_ghost" id="atsAIImprove">✨ Suggest improvements</button>' +
      '</div>' +
      '<div id="atsAIResults" style="margin-top:10px;"></div>' +
    '</div>' +
    // Versions
    '<div class="_ats_right_section">' +
      '<div class="_ats_section_title" style="margin-bottom:8px;">🕓 Version history</div>' +
      '<div id="atsVersions" class="_ats_versions"></div>' +
    '</div>' +
    // Shortcuts
    '<div class="_ats_right_section" style="border-bottom:none; font-size:10px; color:#64748b;">' +
      '<span class="_ats_kbd">Ctrl</span>+<span class="_ats_kbd">S</span> save · ' +
