  // Wire actions
  document.getElementById("atsTest").onclick = _atsActionTestFull;
  document.getElementById("atsRestore").onclick = _atsActionRestore;
  document.getElementById("atsPreviewBtn").onclick = _atsRefreshPreview;
  document.getElementById("atsSuggestValues").onclick = _atsActionAISuggestMock;
  document.getElementById("atsAIReview").onclick = _atsActionAIReview;
  document.getElementById("atsAIDescribe").onclick = _atsActionAIDescribe;
  document.getElementById("atsAIImprove").onclick = _atsActionAIImprove;

  rightEl.querySelectorAll("[data-ats-mock]").forEach(function (inp) {
    inp.oninput = function () {
      var st2 = _atsState();
      st2.mockValues[inp.getAttribute("data-ats-mock")] = inp.value;
    };
  });

  _atsRenderVersions();
}

functions._atsRenderVersions:
function _atsRenderVersions() {
  var box = document.getElementById("atsVersions");
  if (!box) return;
  var tpl = _atsCurrentTemplate();
  var st = _atsState();
  var versions = (st.versions[tpl && tpl.id] || []).slice().reverse();
  if (!versions.length) {
    box.innerHTML = '<div style="font-size:10px; color:#94a3b8;">No previous versions saved yet.</div>';
    return;
  }
  box.innerHTML = versions.slice(0, 8).map(function (v, i) {
    return '<div class="_ats_version_row">' +
      '<span class="_ats_version_row_time">' + new Date(v.at).toLocaleString() + ' · ' + (v.byteSize || 0) + 'B</span>' +
      '<button class="_ats_version_row_btn" data-ats-ver="' + i + '">Restore</button>' +
      '</div>';
  }).join("");
  box.querySelectorAll("[data-ats-ver]").forEach(function (b) {
    b.onclick = function () {
      var idx = parseInt(b.getAttribute("data-ats-ver"), 10);
      var v = versions[idx];
      if (!v) return;
      _atsState().draft = Object.assign({}, tpl, { content: v.content, _dirty: true });
      _atsRenderEditor();
      _atsSetSaveState("dirty");
    };
  });
}

// ── Field edit handler ─────────────────────────────────────────────

functions._atsOnFieldEdit:
function _atsOnFieldEdit() {
  var st = _atsState();
  var base = st.templates.find(function (t) { return t.id === st.currentId; }) || {};
  var draft = Object.assign({}, base);
  draft.name = (document.getElementById("atsFieldName") || {}).value || draft.name;
  draft.agreementType = (document.getElementById("atsFieldType") || {}).value || draft.agreementType;
  draft.status = (document.getElementById("atsFieldStatus") || {}).value || draft.status;
  draft.content = (document.getElementById("atsFieldContent") || {}).value || draft.content;
  draft._dirty = true;
  st.draft = draft;
  _atsSetSaveState("dirty");
  // Debounced auto-save to localStorage (10s) so a refresh doesn't lose work.
  if (st.saveTimer) clearTimeout(st.saveTimer);
  st.saveTimer = setTimeout(function () {
    try {
      window.eli.compat.lsSet("_ats_unsaved_" + draft.id, JSON.stringify({
        content: draft.content, name: draft.name, agreementType: draft.agreementType,
        at: Date.now(),
      }));
      _atsSetSaveState("autosaved");
    } catch (e) { /* tolerate */ }
  }, 10000);
}

functions._atsSetSaveState:
function _atsSetSaveState(state) {
  var el = document.getElementById("atsSaveState");
  if (!el) return;
  el.classList.remove("_ats_saving", "_ats_saved", "_ats_dirty");
  if (state === "saving") { el.textContent = "Saving…"; el.classList.add("_ats_saving"); }
  else if (state === "saved") { el.textContent = "✓ Saved"; el.classList.add("_ats_saved"); }
  else if (state === "autosaved") { el.textContent = "Auto-saved draft"; el.classList.add("_ats_dirty"); }
  else if (state === "dirty") { el.textContent = "Unsaved changes"; el.classList.add("_ats_dirty"); }
  else { el.textContent = ""; }
}

// ── Action handlers ────────────────────────────────────────────────

functions._atsActionSave:
function _atsActionSave() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  if (tpl.locked) {
    if (typeof showToast === "function") showToast("Template is locked — unlock first.", "warn");
    return;
  }
  _atsSetSaveState("saving");
  var st = _atsState();
  // Append to version history (in-memory; persisted to localStorage).
  var prev = st.templates.find(function (t) { return t.id === tpl.id; });
  if (prev) {
    st.versions[tpl.id] = st.versions[tpl.id] || [];
    st.versions[tpl.id].push({
      at: Date.now(), content: prev.content,
      byteSize: String(prev.content || "").length,
    });
    if (st.versions[tpl.id].length > 20) st.versions[tpl.id].shift();
    try { window.eli.compat.lsSet("_ats_versions_" + tpl.id, JSON.stringify(st.versions[tpl.id])); } catch (e) {}
  }
  delete tpl._dirty;
  _atsSave(tpl).then(function () {
    st.draft = null;
    try { window.eli.compat.lsRemove("_ats_unsaved_" + tpl.id); } catch (e) {}
    return _atsLoadAll();
  }).then(function (all) {
    st.templates = all;
    _atsSetSaveState("saved");
    _atsRenderList();
    if (typeof showToast === "function") showToast("Saved " + tpl.name, "ok");
    setTimeout(function () { _atsSetSaveState(""); }, 2000);
  }).catch(function (err) {
    _atsSetSaveState("dirty");
    if (typeof showToast === "function") showToast("Save failed: " + (err && err.message || "unknown"), "err");
  });
}

functions._atsActionDelete:
function _atsActionDelete() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  if (!window.eli.ui || !window.eli.ui.confirm) return;
  window.eli.ui.confirm({
    variant: "danger", icon: "🗑", title: "Delete template?",
    message: "Permanently remove <b>" + _atsEsc(tpl.name || tpl.id) + "</b> from local IDB. Other users won't lose theirs until you push the section via Library Publisher.",
    confirmLabel: "Delete", cancelLabel: "Cancel",
  }).then(function (ok) {
    if (!ok) return;
    _atsDeleteById(tpl.id).then(function () {
      var st = _atsState();
      st.currentId = null; st.draft = null;
      return _atsLoadAll();
    }).then(function (all) {
      _atsState().templates = all;
      _atsRenderList(); _atsRenderEditor(); _atsRenderTestPanel();
      if (typeof showToast === "function") showToast("Deleted", "info");
    });
  });
}

functions._atsActionDuplicate:
function _atsActionDuplicate() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  var copy = Object.assign({}, tpl, {
    id: tpl.id + "_copy_" + Date.now(),
    name: (tpl.name || tpl.id) + " (copy)",
    status: "draft",
    locked: false,
    lastUpdated: Date.now(),
  });
  _atsSave(copy).then(function () {
