functions._atsActionLock:
function _atsActionLock() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  tpl.locked = !tpl.locked;
  _atsSave(tpl).then(function () {
    return _atsLoadAll();
  }).then(function (all) {
    _atsState().templates = all;
    _atsRenderList(); _atsRenderEditor();
    if (typeof showToast === "function") showToast(tpl.locked ? "🔒 Locked" : "🔓 Unlocked", "info");
  });
}

functions._atsActionExport:
function _atsActionExport() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  var blob = new Blob([JSON.stringify(tpl, null, 2)], { type: "application/json" });
  var url = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.href = url;
  a.download = (tpl.id || "template") + ".json";
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
  if (typeof showToast === "function") showToast("Exported", "ok");
}

functions._atsActionDiff:
function _atsActionDiff() {
  var st = _atsState();
  var tpl = _atsCurrentTemplate();
  var saved = st.templates.find(function (t) { return t.id === tpl.id; });
  if (!tpl || !saved) return;
  var diff = _atsSimpleDiff(saved.content || "", tpl.content || "");
  var overlay = document.createElement("div");
  overlay.className = "eli-overlay";
  overlay.style.cssText = "position:fixed; inset:0; z-index:99999; background:rgba(15,23,42,0.55); display:flex; align-items:center; justify-content:center; padding:24px;";
  var html = '<div style="background:#fff; width:min(900px,96vw); max-height:88vh; display:flex; flex-direction:column;">' +
    '<div style="padding:14px 18px; background:linear-gradient(135deg,#0d1b2a,#1b263b); color:#fff; display:flex; justify-content:space-between; align-items:center;">' +
      '<div><div style="font:800 9px/1 Inter,sans-serif; letter-spacing:1.4px; color:#c9a227;">DIFF</div>' +
      '<div style="font:800 16px/1.1 Inter,sans-serif; margin-top:3px;">' + _atsEsc(tpl.name || tpl.id) + ' — current vs saved</div></div>' +
      '<button style="background:none; border:none; color:#fff; font-size:18px; cursor:pointer;" id="atsDiffClose">✕</button>' +
    '</div>' +
    '<div style="padding:8px 16px; background:#f8fafc; font-size:11px; color:#475569;">' +
      '<span class="_ats_diff_line _ats_diff_add" style="padding:1px 4px;">+ ' + diff.filter(function(d){return d.t==="+";}).length + ' added</span> · ' +
      '<span class="_ats_diff_line _ats_diff_del" style="padding:1px 4px;">- ' + diff.filter(function(d){return d.t==="-";}).length + ' removed</span>' +
    '</div>' +
    '<div style="flex:1; overflow-y:auto; padding:8px 16px; font-family:ui-monospace, Consolas, monospace; font-size:11px; background:#fff;">' +
      diff.map(function (d) {
        var cls = d.t === "+" ? "_ats_diff_add" : d.t === "-" ? "_ats_diff_del" : "_ats_diff_eq";
        var p = d.t === "+" ? "+ " : d.t === "-" ? "- " : "  ";
        return '<div class="_ats_diff_line ' + cls + '">' + _atsEsc(p + d.s) + '</div>';
      }).join("") +
    '</div></div>';
  overlay.innerHTML = html;
  document.body.appendChild(overlay);
  document.getElementById("atsDiffClose").onclick = function () { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); };
  overlay.onclick = function (e) { if (e.target === overlay) overlay.remove(); };
}

functions._atsActionTestFull:
function _atsActionTestFull() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  if (typeof showToast === "function") showToast("⏳ Snapshotting doc…", "info");
  _atsSnapshotDoc(tpl.id).then(function (ok) {
    if (!ok) {
      if (typeof showToast === "function") showToast("⚠ Snapshot failed — test will proceed but Restore won't work.", "warn");
    }
    if (typeof showToast === "function") showToast("⏳ Applying template…", "info");
    return _atsApplyToDoc(tpl.content);
  }).then(function () {
    if (typeof showToast === "function") showToast("✓ Applied — use ↩ Restore to undo.", "ok");
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Apply failed: " + (err && err.message || "unknown"), "err");
  });
}

functions._atsActionTestSection:
function _atsActionTestSection(idx) {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  var sections = _atsParseSections(tpl.content);
  var sec = sections[idx];
  if (!sec) {
    if (typeof showToast === "function") showToast("Section not found.", "err");
    return;
  }
  _atsSnapshotDoc(tpl.id).then(function () {
    return _atsApplySection(sec);
  }).then(function () {
    if (typeof showToast === "function") showToast("✓ Section " + (idx + 1) + " applied", "ok");
  }).catch(function (err) {
    if (typeof showToast === "function") showToast("Section apply failed: " + (err && err.message || "unknown"), "err");
  });
}

functions._atsRefreshPreview:
function _atsRefreshPreview() {
  var tpl = _atsCurrentTemplate();
  var st = _atsState();
  var box = document.getElementById("atsPreview");
  if (!box || !tpl) return;
  var rendered = _atsRenderPreview(tpl.content, st.mockValues);
  if (!rendered.trim()) {
    box.innerHTML = '<span class="_ats_preview_empty">(empty)</span>';
    return;
  }
  box.textContent = rendered.slice(0, 4000) + (rendered.length > 4000 ? "\n\n[…truncated]" : "");
}

