functions._atsRenderAILoading:
function _atsRenderAILoading(label) {
  var box = document.getElementById("atsAIResults");
  if (box) box.innerHTML = '<div class="_ats_loading"><span class="_ats_loading_spinner"></span>' + label + '</div>';
}

functions._atsRenderAIError:
function _atsRenderAIError(msg) {
  var box = document.getElementById("atsAIResults");
  if (box) box.innerHTML = '<div class="_ats_ai_issue _ats_ai_error"><div class="_ats_ai_issue_head">AI error</div>' + _atsEsc(msg) + '</div>';
}

functions._atsActionAIReview:
function _atsActionAIReview() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  _atsRenderAILoading("Reviewing template…");
  _atsAIReview(tpl).then(function (data) {
    var issues = (data && data.issues) || [];
    var box = document.getElementById("atsAIResults");
    if (!issues.length) {
      box.innerHTML = '<div class="_ats_ai_issue _ats_ai_info"><div class="_ats_ai_issue_head">no issues</div>AI didn\'t flag anything.</div>';
      return;
    }
    box.innerHTML = '<div class="_ats_ai_results">' + issues.map(function (it) {
      var sev = (it.severity || "info").toLowerCase();
      var cls = sev === "error" ? "_ats_ai_error" : sev === "warn" ? "_ats_ai_warn" : "_ats_ai_info";
      return '<div class="_ats_ai_issue ' + cls + '">' +
        '<div class="_ats_ai_issue_head">' + _atsEsc(sev) + ' · ' + _atsEsc(it.title || "issue") + '</div>' +
        _atsEsc(it.detail || "") +
        '</div>';
    }).join("") + '</div>';
  }).catch(function (err) {
    _atsRenderAIError(err && err.message || "unknown");
  });
}

functions._atsActionAIDescribe:
function _atsActionAIDescribe() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  _atsRenderAILoading("Reading template…");
  _atsAIDescribe(tpl).then(function (text) {
    var box = document.getElementById("atsAIResults");
    box.innerHTML = '<div class="_ats_ai_issue _ats_ai_info">' +
      '<div class="_ats_ai_issue_head">summary</div>' +
      _atsEsc(String(text || "")).replace(/\n/g, "<br>") +
      '</div>';
  }).catch(function (err) { _atsRenderAIError(err && err.message || "unknown"); });
}

functions._atsActionAIImprove:
function _atsActionAIImprove() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  _atsRenderAILoading("Looking for improvements…");
  _atsAIImprovements(tpl).then(function (data) {
    var items = (data && data.improvements) || [];
    var box = document.getElementById("atsAIResults");
    if (!items.length) {
      box.innerHTML = '<div class="_ats_ai_issue _ats_ai_info"><div class="_ats_ai_issue_head">looks solid</div>No improvements suggested.</div>';
