        '<b>' + _atsEsc(it.suggestion || "") + '</b><br>' +
        '<span style="color:#475569;">' + _atsEsc(it.rationale || "") + '</span>' +
        '</div>';
    }).join("") + '</div>';
  }).catch(function (err) { _atsRenderAIError(err && err.message || "unknown"); });
}

functions._atsActionAISuggestMock:
function _atsActionAISuggestMock() {
  var tpl = _atsCurrentTemplate();
  if (!tpl) return;
  if (typeof showToast === "function") showToast("⏳ Generating test values…", "info");
  _atsAISuggestMockValues(tpl).then(function (values) {
    if (!values || typeof values !== "object") {
      if (typeof showToast === "function") showToast("AI returned no values.", "warn");
      return;
    }
    _atsState().mockValues = Object.assign({}, _atsState().mockValues, values);
    _atsRenderTestPanel();
    _atsRefreshPreview();
