functions.showAdminTemplateStudio:
function showAdminTemplateStudio() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ats_root">' +
      '<div class="_ats_header">' +
        '<div class="_ats_header_left">' +
          '<div class="_ats_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ats_header_title">📋 Template Studio</div>' +
          '<div class="_ats_header_sub">Manage, test, and improve Build Draft templates. AI-assisted error finding + per-section testing with one-click restore.</div>' +
        '</div>' +
        '<div id="atsSaveState" class="_ats_header_savestate"></div>' +
      '</div>' +
      '<div class="_ats_body">' +
        // Left rail
        '<div class="_ats_left">' +
          '<div class="_ats_left_search">' +
            '<div class="_ats_left_searchwrap">' +
              '<input id="atsSearch" type="text" placeholder="Filter templates…">' +
            '</div>' +
            '<button class="_ats_btn _ats_btn_gold" id="atsNew">+ New</button>' +
          '</div>' +
          '<div class="_ats_left_filter">' +
            ['all', 'active', 'draft', 'archived'].map(function (s) {
              return '<button data-ats-filter="' + s + '"' + (s === "all" ? ' class="_ats_filter_on"' : '') + '>' + s + '</button>';
            }).join("") +
          '</div>' +
          '<div class="_ats_list" id="atsList"></div>' +
          '<div class="_ats_left_footer">' +
            '<button id="atsImport" class="_ats_secondary">⬆ Import JSON</button>' +
            '<button id="atsBack" class="_ats_secondary">← Home</button>' +
          '</div>' +
        '</div>' +
        '<div class="_ats_center" id="atsCenter"></div>' +
        '<div class="_ats_right" id="atsRight"></div>' +
      '</div>' +
    '</div>';

  // Initial load
  _atsLoadAll().then(function (all) {
    var st = _atsState();
    st.templates = all;
    // Restore version history from localStorage.
    all.forEach(function (t) {
      try {
        var raw = window.eli.compat.lsGet("_ats_versions_" + t.id);
        if (raw) st.versions[t.id] = JSON.parse(raw);
      } catch (e) {}
    });
    _atsRenderList();
    _atsRenderEditor();
    _atsRenderTestPanel();
  });

  // Wire toolbar
  var searchTimer = null;
  document.getElementById("atsSearch").oninput = function () {
    var st = _atsState();
    if (searchTimer) clearTimeout(searchTimer);
    var val = this.value;
    searchTimer = setTimeout(function () {
      st.filterText = val;
      _atsRenderList();
    }, 200);
  };
  document.querySelectorAll("[data-ats-filter]").forEach(function (b) {
    b.onclick = function () {
      document.querySelectorAll("[data-ats-filter]").forEach(function (c) { c.classList.remove("_ats_filter_on"); });
      b.classList.add("_ats_filter_on");
      _atsState().filterStatus = b.getAttribute("data-ats-filter");
      _atsRenderList();
    };
  });
  document.getElementById("atsNew").onclick = _atsActionNew;
  document.getElementById("atsImport").onclick = _atsActionImport;
  document.getElementById("atsBack").onclick = function () {
    if (window.eli.dashboard && window.eli.dashboard.goHome) window.eli.dashboard.goHome();
    else if (window.eli.dashboard && window.eli.dashboard.render) window.eli.dashboard.render();
  };

  // Keyboard shortcuts (active while studio is open).
  var keyHandler = function (e) {
    if ((e.ctrlKey || e.metaKey) && e.key === "s") {
      e.preventDefault(); _atsActionSave();
    } else if ((e.ctrlKey || e.metaKey) && e.key === "d") {
      e.preventDefault(); _atsActionDuplicate();
    } else if (e.key === "Escape") {
      var st = _atsState();
      if (st.draft) { st.draft = null; _atsRenderEditor(); _atsSetSaveState(""); }
    }
  };
  document.addEventListener("keydown", keyHandler);
  // Stash handler so we can remove on view-change (best-effort).
  window._atsKeyHandler = keyHandler;
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateStudio"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminTemplateStudio !== "function") {
      eli.log.event("tool", "admin_template_studio_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Studio failed to load", "err");
      return;
    }
    try { window.showAdminTemplateStudio(); }
    catch (e) {
      eli.log.event("tool", "admin_template_studio_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_template_studio: _show },
    admin_template_studio: { open: _show },
  });

  eli.log.event("tool", "admin_template_studio_initialized", {});
}

jsonTools.css:
/* admin_template_studio — three-pane premium UI matching the rest of
   ELI's navy/gold + light-mode admin surfaces. Class prefix `_ats_`. */

._ats_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  display: flex; flex-direction: column;
  height: 100vh; min-height: 0;
  overflow: hidden;
}

/* ─── Header ─────────────────────────────────────────────────── */
._ats_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 16px 22px;
  border-bottom: 3px solid #c9a227;
  display: flex; justify-content: space-between; align-items: center;
  flex: 0 0 auto;
}
._ats_header_left { display: flex; flex-direction: column; gap: 2px; }
._ats_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif; letter-spacing: 1.4px;
  text-transform: uppercase; color: #c9a227;
}
._ats_header_title { font: 800 20px/1.1 "Book Antiqua", Georgia, serif; margin: 0; }
._ats_header_sub { font-size: 11px; color: rgba(255, 255, 255, 0.7); margin-top: 2px; }
._ats_header_savestate {
  font-size: 10px; font-weight: 700;
  padding: 4px 10px; border-radius: 100px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.85);
  letter-spacing: 0.5px; text-transform: uppercase;
}
._ats_header_savestate._ats_saving { background: rgba(201, 162, 39, 0.25); color: #ffd76b; }
._ats_header_savestate._ats_saved { background: rgba(34, 197, 94, 0.15); color: #6ee7b7; }
._ats_header_savestate._ats_dirty { background: rgba(245, 158, 11, 0.18); color: #fcd34d; }

/* ─── Body: three-pane layout ────────────────────────────────── */
._ats_body {
  display: grid;
  grid-template-columns: minmax(260px, 320px) 1fr minmax(280px, 380px);
  gap: 0;
  flex: 1 1 auto; min-height: 0;
}

/* ─── Left rail: template list ───────────────────────────────── */
._ats_left {
  border-right: 1px solid #e2e8f0;
  background: #fff;
  display: flex; flex-direction: column; min-height: 0;
}
._ats_left_search {
  padding: 12px; border-bottom: 1px solid #f1f5f9;
  display: grid; grid-template-columns: 1fr auto; gap: 8px;
}
._ats_left_searchwrap { position: relative; }
._ats_left_searchwrap input {
  width: 100%; padding: 8px 10px 8px 30px;
  font-size: 11px; border: 1px solid #cbd5e1;
  outline: none; box-sizing: border-box;
}
._ats_left_searchwrap input:focus { border-color: #1565c0; }
._ats_left_searchwrap::before {
  content: "🔍"; position: absolute; left: 10px; top: 50%;
  transform: translateY(-50%); font-size: 12px; pointer-events: none;
}
._ats_left_filter {
  display: flex; padding: 0 12px 8px 12px; gap: 4px;
  flex-wrap: wrap;
}
._ats_left_filter button {
  padding: 4px 9px; font: 700 9px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: #f1f5f9; color: #64748b;
  border: 1px solid #e2e8f0; cursor: pointer;
  transition: all 0.15s;
}
._ats_left_filter button._ats_filter_on {
  background: #0f172a; color: #fff; border-color: #0f172a;
}
._ats_left_filter button:hover:not(._ats_filter_on) {
  background: #e2e8f0; color: #1565c0;
}

._ats_list {
  flex: 1 1 auto; overflow-y: auto; padding: 4px;
}
._ats_card {
  display: block; padding: 10px 12px;
  border: 1px solid #e2e8f0; background: #fff;
  margin-bottom: 4px; cursor: pointer;
  transition: all 0.15s;
  position: relative;
}
._ats_card:hover { border-color: #cbd5e1; background: #f8fafc; }
._ats_card._ats_card_active {
  border-color: #1565c0; background: linear-gradient(180deg, #fff, #e3f2fd 130%);
  box-shadow: inset 3px 0 0 #1565c0;
}
._ats_card_title { font-size: 12px; font-weight: 700; color: #0f172a; margin-bottom: 3px; }
._ats_card_meta { font-size: 10px; color: #64748b; display: flex; gap: 6px; align-items: center; }
._ats_card_pill {
  font: 800 8px/1 Inter, sans-serif; letter-spacing: 0.5px;
  padding: 2px 6px; text-transform: uppercase;
}
._ats_pill_active   { background: #dcfce7; color: #166534; }
._ats_pill_draft    { background: #fef3c7; color: #92400e; }
._ats_pill_archived { background: #f1f5f9; color: #64748b; }
._ats_pill_locked   { background: #ede9fe; color: #6d28d9; }

._ats_left_footer {
  padding: 10px 12px; border-top: 1px solid #f1f5f9;
  display: flex; gap: 6px;
}
._ats_left_footer button {
  flex: 1; padding: 8px; font: 700 10px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: #c9a227; color: #0d1b2a;
  border: none; cursor: pointer;
  transition: filter 0.15s;
}
._ats_left_footer button:hover { filter: brightness(0.95); }
._ats_left_footer button._ats_secondary {
  background: #fff; color: #475569; border: 1px solid #cbd5e1;
}

/* ─── Center pane: editor ────────────────────────────────────── */
._ats_center {
  display: flex; flex-direction: column; min-height: 0;
  background: #f8fafc; overflow-y: auto;
}
._ats_center_empty {
  flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; color: #94a3b8; padding: 40px;
}
._ats_center_empty_icon { font-size: 64px; opacity: 0.4; margin-bottom: 12px; }
._ats_center_empty_title { font-size: 14px; font-weight: 700; color: #475569; margin-bottom: 6px; }
._ats_center_empty_sub { font-size: 12px; }

._ats_section { padding: 16px 20px; border-bottom: 1px solid #e2e8f0; background: #fff; }
._ats_section + ._ats_section { margin-top: 0; }
._ats_section_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 10px;
}
._ats_section_title {
  font: 800 10px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.6px; color: #475569;
}
._ats_section_actions { display: flex; gap: 4px; }

._ats_meta_grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
  margin-bottom: 8px;
}
._ats_field_label {
  font: 700 9px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #64748b; margin-bottom: 4px;
}
._ats_input, ._ats_select, ._ats_textarea {
  width: 100%; padding: 8px 10px; font-size: 12px;
  border: 1px solid #cbd5e1; outline: none;
  background: #fff; color: #0f172a; box-sizing: border-box;
  transition: border-color 0.15s;
}
._ats_input:focus, ._ats_select:focus, ._ats_textarea:focus { border-color: #1565c0; }
._ats_textarea {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 11px; line-height: 1.5;
  min-height: 200px; resize: vertical;
}
._ats_textarea._ats_textarea_large { min-height: 380px; }

._ats_outline_grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
}
._ats_outline_box {
  border: 1px solid #e2e8f0; padding: 10px; background: #fff;
  min-height: 80px;
}
._ats_outline_head {
  font: 800 9px/1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px; color: #475569; margin-bottom: 8px;
  display: flex; justify-content: space-between; align-items: center;
}
._ats_outline_head_count {
  background: #1565c0; color: #fff; padding: 2px 6px;
  font-size: 9px; font-weight: 800; border-radius: 100px;
}
._ats_tag_list { display: flex; flex-wrap: wrap; gap: 4px; }
._ats_tag {
  padding: 3px 7px; font: 700 10px/1 ui-monospace, Consolas, monospace;
  background: #ede9fe; color: #6d28d9;
  cursor: pointer; transition: filter 0.15s;
}
._ats_tag:hover { filter: brightness(0.95); }
._ats_section_list { display: flex; flex-direction: column; gap: 4px; }
._ats_section_row {
  padding: 6px 8px; font-size: 11px;
  background: #f8fafc; border: 1px solid #e2e8f0;
  display: flex; justify-content: space-between; align-items: center;
}
._ats_section_row_label { font-weight: 700; color: #0f172a; }
._ats_section_row_test {
  font: 700 9px/1 Inter, sans-serif; text-transform: uppercase;
  padding: 4px 8px; background: #1565c0; color: #fff;
  border: none; cursor: pointer; letter-spacing: 0.4px;
}
._ats_section_row_test:hover { background: #0d47a1; }

._ats_btn {
  padding: 7px 12px; font: 800 10px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  border: none; cursor: pointer;
  transition: all 0.15s;
  display: inline-flex; align-items: center; gap: 5px;
}
._ats_btn:disabled { opacity: 0.5; cursor: progress; }
._ats_btn_primary { background: #1565c0; color: #fff; }
._ats_btn_primary:hover:not(:disabled) { background: #0d47a1; }
._ats_btn_gold { background: #c9a227; color: #0d1b2a; }
._ats_btn_gold:hover:not(:disabled) { filter: brightness(0.95); }
._ats_btn_ghost {
  background: #fff; color: #475569; border: 1px solid #cbd5e1;
}
._ats_btn_ghost:hover:not(:disabled) { border-color: #1565c0; color: #1565c0; }
._ats_btn_danger {
  background: #fff; color: #b91c1c; border: 1px solid #fca5a5;
}
._ats_btn_danger:hover:not(:disabled) { background: #fef2f2; }
._ats_btn_success { background: #16a34a; color: #fff; }
._ats_btn_success:hover:not(:disabled) { background: #15803d; }

/* ─── Right pane: test panel ─────────────────────────────────── */
._ats_right {
  border-left: 1px solid #e2e8f0;
  background: #fff;
  display: flex; flex-direction: column; min-height: 0;
  overflow-y: auto;
}
._ats_right_head {
  padding: 12px 14px; background: linear-gradient(135deg, #1e3a8a, #1565c0);
  color: #fff;
  font: 800 10px/1.1 Inter, sans-serif; text-transform: uppercase;
  letter-spacing: 0.5px;
}
._ats_right_section { padding: 14px; border-bottom: 1px solid #e2e8f0; }

._ats_actionbar { display: flex; flex-direction: column; gap: 6px; }
._ats_actionbar ._ats_btn { width: 100%; justify-content: center; padding: 9px; }

._ats_mocklist { display: flex; flex-direction: column; gap: 6px; }
._ats_mockrow {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
  gap: 6px; align-items: center;
}
._ats_mockrow_label {
  font: 700 10px/1 ui-monospace, Consolas, monospace;
  color: #6d28d9; padding: 6px 8px;
  background: #ede9fe; overflow: hidden;
  text-overflow: ellipsis; white-space: nowrap;
}
._ats_mockrow input {
  padding: 6px 8px; font-size: 11px; border: 1px solid #cbd5e1;
  outline: none; box-sizing: border-box;
}
._ats_mockrow input:focus { border-color: #1565c0; }

._ats_preview {
  padding: 12px; background: #fffbeb; border: 1px solid #fde68a;
  font: 500 11px/1.55 Georgia, serif; color: #0f172a;
  max-height: 280px; overflow-y: auto; white-space: pre-wrap;
}
._ats_preview_empty { color: #94a3b8; font-style: italic; }

._ats_ai_results { display: flex; flex-direction: column; gap: 8px; }
._ats_ai_issue {
  padding: 8px 10px; border-left: 4px solid;
  background: #fff; font-size: 11px; line-height: 1.5;
}
._ats_ai_issue._ats_ai_error { border-color: #dc2626; background: #fef2f2; }
._ats_ai_issue._ats_ai_warn  { border-color: #f59e0b; background: #fffbeb; }
._ats_ai_issue._ats_ai_info  { border-color: #1565c0; background: #eff6ff; }
._ats_ai_issue_head {
  font-weight: 800; text-transform: uppercase; letter-spacing: 0.4px;
  font-size: 9px; margin-bottom: 4px;
}
._ats_ai_issue._ats_ai_error ._ats_ai_issue_head { color: #b91c1c; }
._ats_ai_issue._ats_ai_warn  ._ats_ai_issue_head { color: #92400e; }
._ats_ai_issue._ats_ai_info  ._ats_ai_issue_head { color: #1565c0; }

._ats_loading {
  padding: 20px; text-align: center; font-size: 11px; color: #64748b;
}
._ats_loading_spinner {
  display: inline-block; width: 14px; height: 14px;
  border: 2px solid #e2e8f0; border-top-color: #1565c0;
  border-radius: 50%; animation: _ats_spin 0.8s linear infinite;
  margin-right: 6px; vertical-align: middle;
}
@keyframes _ats_spin { to { transform: rotate(360deg); } }

._ats_versions { max-height: 240px; overflow-y: auto; }
._ats_version_row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 8px; font-size: 11px;
  border-bottom: 1px solid #f1f5f9;
}
._ats_version_row:hover { background: #f8fafc; }
._ats_version_row_time { color: #64748b; font-size: 10px; font-family: ui-monospace, monospace; }
._ats_version_row_btn {
  font: 700 9px/1 Inter, sans-serif; text-transform: uppercase;
  padding: 4px 7px; background: #fff; color: #1565c0;
  border: 1px solid #cbd5e1; cursor: pointer;
}
._ats_version_row_btn:hover { background: #eff6ff; border-color: #1565c0; }

._ats_kbd {
  font: 700 9px/1 ui-monospace, Consolas, monospace;
  padding: 2px 5px; background: #f1f5f9; color: #475569;
  border: 1px solid #cbd5e1; border-bottom-width: 2px;
}

._ats_diff_line { font: 500 11px/1.5 ui-monospace, Consolas, monospace; padding: 1px 6px; }
._ats_diff_add { background: #dcfce7; color: #166534; }
._ats_diff_del { background: #fef2f2; color: #b91c1c; text-decoration: line-through; }
._ats_diff_eq  { color: #94a3b8; }

._ats_dropzone {
  padding: 18px; text-align: center; border: 2px dashed #cbd5e1;
  background: #f8fafc; color: #94a3b8; font-size: 11px;
  cursor: pointer; transition: all 0.15s;
}
._ats_dropzone:hover, ._ats_dropzone._ats_dragover {
  border-color: #1565c0; background: #eff6ff; color: #1565c0;
}
